# Reviewed under AGENTS.md
class Money:
    """An amount of money, stored as a whole number of cents."""

    __slots__ = ('cents',)

    def __init__(self, cents: int):
        if not isinstance(cents, int) or isinstance(cents, bool):
            raise TypeError(f'cents must be an int, got {cents!r}')
        self.cents = cents

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents + other.cents)

    def __radd__(self, other):
        return self.__add__(other)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents - other.cents)

    def __mul__(self, n: int):
        if not isinstance(n, int) or isinstance(n, bool):
            return NotImplemented
        return Money(self.cents * n)

    __rmul__ = __mul__

    def __neg__(self):
        return Money(-self.cents)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents

    def __hash__(self):
        return hash(self.cents)

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        return f'{sign}${abs(self.cents) / 100:,.2f}'

    def split(self, n: int) -> list['Money']:
        """Split this amount into ``n`` parts whose sum is exactly this amount.

        The parts differ by at most one cent; any remainder is handed out one
        cent at a time starting from the first part.
        """
        if not isinstance(n, int) or isinstance(n, bool):
            raise TypeError(f'n must be an int, got {n!r}')
        if n < 1:
            raise ValueError(f'cannot split money into {n} parts')
        share, remainder = divmod(self.cents, n)
        return [Money(share + (1 if i < remainder else 0)) for i in range(n)]
